import {ProductionPreview} from '../material-production/preview.js';
import {loadProductionMaterial} from '../material-production/loader.js';
const $=id=>document.getElementById(id),preview=new ProductionPreview();let busy=false;
async function change(action){if(busy)return;busy=true;document.body.dataset.busy='true';try{const begin=performance.now();await action();await preview.idle();await preview.renderer.renderAsync(preview.scene,preview.camera);await preview.device.queue.onSubmittedWorkDone();document.body.dataset.frame=String(Number(document.body.dataset.frame||0)+1);$('caption').querySelector('strong').textContent=$('enhanced').checked?'Shared surface environment':'Repeating base maps';$('modeDescription').textContent=$('enhanced').checked?'Stochastic detail, broad variation, sheltered surfaces, anchored runoff, repairs and contact deposits.':'Baseline: the same geometry, prepared maps and lighting, without the shared environment layer.';$('status').textContent=`WebGPU · ${$('zone').selectedOptions[0].textContent} · ${$('enhanced').checked?'9 correlated PBR samples + up to 9 near detail samples':'base maps only'} · last scene update ${(performance.now()-begin).toFixed(1)} ms`;document.body.dataset.environmentReady='true';}catch(e){document.body.dataset.error=e.message;$('status').textContent=e.message;console.error(e);}finally{busy=false;document.body.dataset.busy='false';}}
await preview.init($('viewport'));await preview.shape('assembly');const catalog=await(await fetch(new URL('../material-production/catalog.json',import.meta.url))).json(),entry=catalog.entries.find(e=>e.id==='coastal'),result=await loadProductionMaterial(entry);await change(async()=>{await preview.apply(result.pack);preview.zone(Number($('zone').value));preview.light('raking');});
$('zone').onchange=()=>change(async()=>preview.zone(Number($('zone').value)));$('enhanced').onchange=()=>change(()=>preview.setEnvironment($('enhanced').checked));$('light').onchange=()=>change(async()=>preview.light($('light').value));
const view=(target,position)=>change(async()=>{preview.controls.target.set(...target);preview.camera.position.set(...position);preview.controls.update();preview.dirty=true;});$('overview').onclick=()=>view([0,1.8,.3],[8.5,6.4,13]);$('close').onclick=()=>view([.8,2.5,.15],[3.5,3.2,5.2]);$('contact').onclick=()=>view([.4,.35,.4],[2.6,1.35,3.2]);$('corner').onclick=()=>view([-3.5,1.5,.6],[.3,3.6,6]);
window.addEventListener('pagehide',()=>preview.dispose(),{once:true});
